import type { ReactNode } from 'react';
import { cx } from '@/lib/cx';
import './index-row.css';

/**
 * B56 · IndexRow — the numbered contents strip under the masthead. One job:
 * state a publication's sections as a numbered strip, and link to them.
 *
 * It is the cover's contents row: a horizontal strip of cells divided by
 * vertical hairlines, each carrying an ordinal, the section's name, and an
 * optional mono count. F11 is untouched by it — where the reference cover
 * prints a picture, a 76° page prints the places the reader can go next.
 *
 * Three components look alike here and are not interchangeable, so the
 * division is written down before someone reaches for the wrong one. **B1
 * `BandNav` is the SITE's navigation**: it is chrome, it sits on ink, it
 * travels every page, and it names the sections of the product. **B48
 * `FeatureList` states what the product DOES** and nothing in it is
 * clickable. **B56 states what THIS page contains**, and every cell goes
 * somewhere. Pick by what the reader gets: chrome, a claim, or a contents
 * page. A strip that names the app's sections is BandNav wearing a costume.
 *
 * It carries no seed FILL and no coloured block (F14): the one seed
 * rectangle on a public page belongs to the action, and this row asks for
 * nothing — it points. The seed appears here only as the colour the label
 * takes under a pointer, which is B10's text-link behaviour on a link.
 *
 * Don't: no icons or tiles per cell; no ninth section (that is a sitemap);
 * no active/current state — the strip indexes ONE page's contents, and a
 * contents line that marks itself as "where you are" is the band's job
 * (B1) or a breadcrumb by another name (F13); never a horizontal scroller
 * (A2's ban is written for the band and reads on every nav-like row).
 */
export interface IndexItem {
  id: string;
  /** The section's name. One or two words — this is a contents line. */
  label: string;
  href: string;
  /** Mono, under the label: a count, a version, a file type. */
  meta?: string;
}

/** Adapter for router links — keeps the strip router-agnostic, exactly as
    BandNav's does. Same shape, same fallback, so one function wires the
    band, the footer and the contents strip alike. */
type RenderLink = (item: IndexItem, className: string) => ReactNode;

export interface IndexRowProps {
  /** Two to eight. A ninth section is a sitemap, not a contents strip. */
  items: IndexItem[];
  /** REQUIRED, not optional as it is on B48 and B50. Those are statements
      and a name is a courtesy; this is a `<nav>` landmark, and an unnamed
      one is announced as "navigation" beside the band's — two identical
      unlabelled landmarks on one page is the defect B51 exists to make
      impossible (A4). */
  ariaLabel: string;
  /** Router adapter, exactly as BandNav takes one. Falls back to `<a>`. */
  renderLink?: (item: IndexItem, className: string) => ReactNode;
  className?: string;
}

/* The ordinal is derived from POSITION, never passed in — B48's rule and
   its reasoning, which apply with more force here: a hand-written number
   drifts the moment a section is inserted, and a contents page that
   miscounts itself sends the reader to the wrong place rather than merely
   embarrassing itself. Two digits is the ceiling the cap already assumes. */
const ordinal = (index: number) => String(index + 1).padStart(2, '0');

function fallbackLink(item: IndexItem, className: string) {
  return (
    <a href={item.href} className={className}>
      {item.label}
    </a>
  );
}

function toLink(item: IndexItem, className: string, renderLink?: RenderLink) {
  return renderLink ? renderLink(item, className) : fallbackLink(item, className);
}

export function IndexRow({ items, ariaLabel, renderLink, className }: IndexRowProps) {
  return (
    /* A real <nav>, named. The `ol` inside it is ORDERED because the
       ordinals are the point: 03 is the third section, not a decorative
       numeral beside it, and a <ul> would leave the count to the eye. */
    <nav className={cx('sv-index', className)} aria-label={ariaLabel}>
      {/* `role="list"` is not a restated implicit role for its own sake:
          `list-style: none` is what strips the list semantics in WebKit,
          and this is the one list in the system whose COUNT and ORDER are
          the information. The markers are removed because the ordinal is
          printed at display size two lines above where a marker would sit.

          The count travels as data, exactly as B48's column count does — a
          literal in an inline style would put the wrap back in the
          component and out of the stylesheet's reach. */}
      <ol className="sv-index__list" role="list" data-count={items.length}>
        {items.map((item, index) => (
          <li className="sv-index__cell" key={item.id}>
            {/* NOT aria-hidden, for B48's reason: copy refers to sections
                by number ("see 03"), and hiding a visible figure from a
                screen reader is the asymmetry C5 warns about. It is also
                deliberately OUTSIDE the anchor — inside it, the link's
                accessible name would be "01 Components", and a link that
                renames itself every time a section is inserted above it is
                a link nobody can refer to twice. Soft ink, never faint: a
                number that is read is content (C2). */}
            <span className="sv-index__ordinal sv-num">{ordinal(index)}</span>
            {/* The LABEL is the anchor, not the cell. The router adapter's
                shape is BandNav's verbatim — it is handed the item and a
                class and renders the item's own label — so a cell-sized
                anchor would have to compose an anatomy the caller's router
                cannot know about, and the ordinal and meta would vanish
                from every routed page while surviving the fallback. A
                cell-sized hit area with no visible affordance is mystery
                meat besides (A2); the words that name the section are what
                the reader aims at, and they carry their own hit area. */}
            {toLink(item, 'sv-index__link', renderLink)}
            {item.meta && <span className="sv-index__meta sv-mono">{item.meta}</span>}
          </li>
        ))}
      </ol>
    </nav>
  );
}

/* B56 · IndexRow — the cover's contents row: vertical hairlines and nothing
   else. No card, no tile, no fill, no rule around the strip. The lines
   BETWEEN the cells are what make eight sections read as one contents page
   rather than as eight buttons — the same physics as B50 ProofRow, turned
   from figures to destinations. */

@layer sv-components {
  /* grid-auto-flow: column gives the strip its own column count — two to
     eight items land as two to eight equal tracks with no prop, no literal
     and no inline style to keep in step with the array (B50). Rule 19 ·
     minmax(0, …) on every track, never a bare 1fr: a grid item's default
     min-width is auto, so one long section name would widen its track and
     push the page sideways (C7, Part E). */
  .sv-index__list {
    display: grid;
    grid-auto-flow: column;
    grid-auto-columns: minmax(0, 1fr);
    column-gap: var(--sv-s5);
    row-gap: var(--sv-s5);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /* Cells stretch to the tallest in the strip, so the hairlines are one
     length whatever the meta lines do. */
  .sv-index__cell {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    overflow-wrap: anywhere;
  }

  /* The rule sits BETWEEN cells, so it belongs to the second of each pair
     and never to the first: a hairline before the first cell would fence
     the strip off from the masthead it belongs to, and the first ordinal
     must sit on the page's own left edge — the strip is edge-set, like the
     display title above it. The gap opens the space left of the rule, the
     padding opens it right, so the line stays off the type on both sides. */
  .sv-index__cell + .sv-index__cell {
    padding-left: var(--sv-s5);
    border-left: 1px solid var(--sv-line);
  }

  /* RULE 20 · THE ONE DISPLAY-FACE MARK IN THIS COMPONENT, and the case for
     it, since the rule asks for one either way.

     The ordinal is the only element here that is not language: the label is
     read, the meta is metadata, and the numeral is the COVER'S DEVICE — the
     mark the reference actually sets large. Set in mono at 10px it would be
     B48's ordinal, and B56 would differ from a FeatureList by layout alone,
     which is not a difference the taxonomy accepts (A2's "generic marketing
     widget" is the same defect as its admin twin). So the ordinal takes
     --sv-font-display: the public surface's own voice, spent on the public
     surface's own mark, in the file the firewall registers for it.

     What it does NOT take is the width axis. That axis is the Masthead's
     instrument — it exists so a 64px claim can survive 320px — and a
     two-digit numeral at a fixed 20px has no width problem to solve. An
     axis turned because it is there is a slot filled because it exists
     (F12's failure, in a stylesheet).

     Nor does it take a display STEP: rule 17 fences --sv-display-1/2/3 to
     masthead.css, cta.css and proof-row.css, and this file is deliberately
     absent from that list. 20px sits INSIDE the product ramp, below the
     27px h1, so the contents strip can never speak above the claim it sits
     under. Tabular via .sv-num (A4), reused rather than restated, so 01 and
     11 are one width down the strip and the labels start on one line. */
  .sv-index__ordinal {
    font-family: var(--sv-font-display);
    font-size: 20px;
    font-weight: 700;
    line-height: 1;
    letter-spacing: -0.01em;
    color: var(--sv-ink-soft);
  }

  /* B10's text-link rule: no underline until hover, and hover carries the
     seed. inline-flex plus the vertical padding puts the hit area over 24px
     without the line growing — the padding sits inside the line's own
     leading, so nothing moves on hover and only colour transitions (A1). */
  .sv-index__link {
    display: inline-flex;
    margin-top: var(--sv-s2);
    padding: var(--sv-s1) 0;
    font-size: 14px;
    font-weight: 700;
    line-height: 1.3;
    color: var(--sv-ink);
    text-decoration: none;
    transition: color var(--sv-t-fast);
  }

  .sv-index__link:hover {
    color: var(--sv-seed-text);
    text-decoration: underline;
  }

  /* Focus takes the same colour and NOTHING else: the C3 ring is already
     drawn on every :focus-visible in base.css, and a component that
     restates it is a component that will drift from it. */
  .sv-index__link:focus-visible {
    color: var(--sv-seed-text);
  }

  /* Soft, not faint — a count is read (C2). */
  .sv-index__meta {
    margin-top: var(--sv-s1);
    color: var(--sv-ink-soft);
  }

  /* ---- The wrap ---- */

  /* C7 · eight cells cannot hold eight columns on a tablet, so the strip
     WRAPS. It never scrolls sideways: A2's ban is written for the band and
     it reads on every nav-like row.

     The column count is fixed per band rather than derived from the item
     count, because a rule can only be dropped where a line is KNOWN to
     start. Two columns is the floor every count degrades into — including
     an out-of-spec ninth cell, which wraps correctly rather than breaking
     — and the counts that would otherwise leave four rows of two take
     three or four columns instead, so the strip lands in two rows. */
  @media (max-width: 860px) {
    .sv-index__list {
      grid-auto-flow: row;
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    /* B50's rule verbatim: every cell that STARTS a line drops its own. A
       rule at the start of the second row divides nothing from nothing,
       and a rule between nothing and nothing is worse than no rule at all
       — it also pushes column one out of line with the column above it. */
    .sv-index__cell:nth-child(2n + 1) {
      padding-left: 0;
      border-left: 0;
    }

    /* Five and six cells: three columns, two rows. The rule is restored on
       every cell first, because the two-column selector above has already
       cleared cells that are no longer line starts. */
    .sv-index__list[data-count='5'],
    .sv-index__list[data-count='6'] {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .sv-index__list[data-count='5'] .sv-index__cell,
    .sv-index__list[data-count='6'] .sv-index__cell {
      padding-left: var(--sv-s5);
      border-left: 1px solid var(--sv-line);
    }

    .sv-index__list[data-count='5'] .sv-index__cell:nth-child(3n + 1),
    .sv-index__list[data-count='6'] .sv-index__cell:nth-child(3n + 1) {
      padding-left: 0;
      border-left: 0;
    }

    /* Seven and eight cells: four columns, two rows. */
    .sv-index__list[data-count='7'],
    .sv-index__list[data-count='8'] {
      grid-template-columns: repeat(4, minmax(0, 1fr));
    }

    .sv-index__list[data-count='7'] .sv-index__cell,
    .sv-index__list[data-count='8'] .sv-index__cell {
      padding-left: var(--sv-s5);
      border-left: 1px solid var(--sv-line);
    }

    .sv-index__list[data-count='7'] .sv-index__cell:nth-child(4n + 1),
    .sv-index__list[data-count='8'] .sv-index__cell:nth-child(4n + 1) {
      padding-left: 0;
      border-left: 0;
    }
  }

  /* ---- The floor ---- */

  /* One column: the strip stands up, and the hairline turns 90° with it.
     Every cell starts a line, so no cell can carry a vertical rule — and a
     stack held apart by gaps alone stops reading as a contents page. What
     replaces it is B48's column rule: one 1px line OVER each cell, with the
     ordinal, the label and the count hanging below it. Nothing hides,
     nothing scrolls, and the structure is the same structure rotated.

     The attribute selector is repeated so these rules outrank the
     [data-count='5'] declarations above — a four-across strip must be able
     to become one-across. */
  @media (max-width: 560px) {
    .sv-index__list[data-count] {
      grid-template-columns: minmax(0, 1fr);
      row-gap: var(--sv-s4);
    }

    .sv-index__list[data-count] .sv-index__cell {
      padding-top: var(--sv-s3);
      padding-left: 0;
      border-top: 1px solid var(--sv-line);
      border-left: 0;
    }
  }
}
